INSERT INTO `announcements` (`id`, `title`, `content`, `created_by`, `created_at`) VALUES
(1, 'Chào mừng bạn đến với hệ thống quản lý nhân viên', 'Từ hôm nay, mọi thông báo của công ty sẽ được đăng tại Bảng tin này. Hãy mở app mỗi ngày để không bỏ lỡ thông tin quan trọng về lịch làm việc, nghỉ phép và bảng lương.', NULL, '2026-11-05 16:44:25'),
(2, 'Nhắc nhở: chấm công trước 8h15', 'Để tránh bị ghi nhận đi muộn, mọi người nhớ chấm công vào ngay khi tới công ty. Trường hợp quên chấm công, hãy liên hệ phòng IT hoặc quản lý trực tiếp trong ngày để được hỗ trợ ghi nhận bổ sung.', NULL, '2026-11-06 16:44:25'),
(3, 'Lịch trả lương tháng này', 'Bảng lương sẽ được cập nhật lên mục Bảng lương trong app vào ngày cuối tháng. Nếu có thắc mắc về phụ cấp, tăng ca hoặc khấu trừ, vui lòng gửi đơn/gặp phòng nhân sự trước ngày chốt lương.', NULL, '2026-11-07 16:44:25');

